BEGIN;
SELECT plan(46);
INSERT INTO public.tenants(id,name_ar,name_en) VALUES('a9500000-0000-4000-8000-000000000001','Payroll fixture','Payroll fixture'),('a9500000-0000-4000-8000-000000000002','Other fixture','Other fixture');
INSERT INTO auth.users(id,email) VALUES('a9500000-0000-4000-8000-000000000003','payroll-preparation@example.test');
INSERT INTO public.users(id,auth_user_id,tenant_id,email,role,status,must_change_password) VALUES('a9500000-0000-4000-8000-000000000004','a9500000-0000-4000-8000-000000000003','a9500000-0000-4000-8000-000000000001','payroll-preparation@example.test','general_manager','active',false);
INSERT INTO public.drivers(id,tenant_id,full_name_ar,primary_mobile,category,status,hire_date) VALUES('a9500000-0000-4000-8000-000000000005','a9500000-0000-4000-8000-000000000001','Pay fixture','0509500001','sponsored_type1','active','2025-01-01'),('a9500000-0000-4000-8000-000000000006','a9500000-0000-4000-8000-000000000002','Other fixture','0509500002','sponsored_type1','active','2025-01-01');
INSERT INTO public.delivery_platforms(id,tenant_id,code,name_ar) VALUES('a9500000-0000-4000-8000-000000000007','a9500000-0000-4000-8000-000000000001','PAY95','Payroll test');
CREATE TEMP TABLE payroll_fixture(rule jsonb,rule_id uuid,advance_id uuid,period_id uuid);
INSERT INTO payroll_fixture(rule) VALUES('{"driverId":"a9500000-0000-4000-8000-000000000005","category":"sponsored_type1","effectiveDate":"2026-02-01","workingDaysTarget":24,"targetOrders":300,"baseSalary":2700.25,"bonusRate":0,"deductionRate":0,"minimumNetFloor":0,"note":"Owner reviewed explicit rule"}');
GRANT SELECT,UPDATE ON payroll_fixture TO authenticated;
SELECT ok(NOT has_function_privilege('anon','public.payroll_preparation_mutate(text,jsonb)','EXECUTE'),'Anonymous cannot mutate preparation');
SELECT ok(NOT has_table_privilege('authenticated','public.driver_payroll_rules','UPDATE'),'Rules cannot bypass workflow');
SELECT ok(NOT has_table_privilege('authenticated','public.monthly_driver_orders','INSERT'),'Derived orders cannot bypass workflow');
SELECT ok(NOT EXISTS(SELECT 1 FROM unnest(ARRAY['public.payroll_preparation_reviews','public.payroll_period_bases']) tab WHERE has_table_privilege('anon',tab,'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER')),'Anonymous roles have no review or basis privileges');
SELECT ok(NOT EXISTS(SELECT 1 FROM unnest(ARRAY['public.payroll_preparation_reviews','public.payroll_period_bases']) tab WHERE has_table_privilege('authenticated',tab,'INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER')),'Authenticated roles cannot bypass reviewed payroll inputs with table writes or DDL privileges');
SELECT ok(NOT EXISTS(SELECT 1 FROM unnest(ARRAY['public.payroll_preparation_reviews','public.payroll_period_bases']) tab WHERE NOT has_table_privilege('authenticated',tab,'SELECT')),'Caller read access to preparation and bases remains available under RLS');
SET LOCAL ROLE anon;
SELECT throws_ok($$TRUNCATE public.payroll_preparation_reviews$$,'42501',NULL,'Anonymous cannot erase payroll reviews with TRUNCATE');
SELECT throws_ok($$TRUNCATE public.payroll_period_bases CASCADE$$,'42501',NULL,'Anonymous cannot erase frozen payroll bases with TRUNCATE');
RESET ROLE;
SET LOCAL ROLE authenticated;
SELECT throws_ok($$TRUNCATE public.payroll_preparation_reviews$$,'42501',NULL,'Authenticated cannot erase reviewed payroll source with TRUNCATE');
SELECT throws_ok($$TRUNCATE public.payroll_period_bases CASCADE$$,'42501',NULL,'Authenticated cannot erase frozen payroll bases with TRUNCATE');
RESET ROLE;
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub','a9500000-0000-4000-8000-000000000003',true);
SELECT set_config('request.jwt.claims','{"sub":"a9500000-0000-4000-8000-000000000003","role":"authenticated","aal":"aal1"}',true);
SELECT throws_ok($$SELECT public.payroll_preparation_read(2026,2)$$,'42501','PAY_PREPARATION_FORBIDDEN','MFA is enforced within RPC');
SELECT set_config('request.jwt.claims','{"sub":"a9500000-0000-4000-8000-000000000003","role":"authenticated","aal":"aal2"}',true);
SELECT throws_ok($$SELECT public.payroll_preparation_mutate('rule_save',rule-'baseSalary') FROM payroll_fixture$$,'P0001','PAY_RULE_INCOMPLETE','No salary defaults invented');
SELECT throws_ok($$SELECT public.payroll_preparation_mutate('rule_save',jsonb_set(rule,'{driverId}','"a9500000-0000-4000-8000-000000000006"')) FROM payroll_fixture$$,'P0001','PAY_DRIVER_NOT_FOUND','Foreign-tenant driver rejected');
SELECT lives_ok($$UPDATE payroll_fixture SET rule_id=(public.payroll_preparation_mutate('rule_save',rule)->>'id')::uuid$$,'Explicit rule created');
SELECT lives_ok($$SELECT public.payroll_preparation_mutate('rule_save',rule||jsonb_build_object('id',rule_id,'expectedVersion',1)) FROM payroll_fixture$$,'Unused rule updated with version');
SELECT throws_ok($$SELECT public.payroll_preparation_mutate('rule_archive',jsonb_build_object('id',rule_id,'expectedVersion',1,'note','Stale version rejected')) FROM payroll_fixture$$,'P0001','PAY_STALE_VERSION','Stale rule version rejected');
SELECT lives_ok($$SELECT public.payroll_preparation_mutate('open','{"year":2026,"month":2,"workingDays":24}')$$,'Explicit preparation period opened');
SELECT throws_ok($$SELECT public.payroll_preparation_mutate('attendance_save','{"year":2026,"month":2,"driverId":"a9500000-0000-4000-8000-000000000005","expectedVersion":0,"days":[],"note":"Missing source data"}')$$,'P0001','PAY_ATTENDANCE_INCOMPLETE','Missing days rejected');
SELECT throws_ok($$SELECT public.payroll_preparation_mutate('lock',jsonb_build_object('year',2026,'month',2,'expectedVersion',1,'note','Review incomplete inputs'))$$,'P0001','PAY_DRIVER_INPUTS_UNREVIEWED','Unreviewed inputs cannot lock');
SELECT lives_ok($$SELECT public.payroll_preparation_mutate('attendance_save',jsonb_build_object('year',2026,'month',2,'driverId','a9500000-0000-4000-8000-000000000005','expectedVersion',0,'note','Every calendar day reviewed','days',(SELECT jsonb_agg(jsonb_build_object('date',to_char(d,'YYYY-MM-DD'),'status',CASE WHEN extract(day FROM d)<=20 THEN 'present' WHEN extract(day FROM d)=21 THEN 'half_day' WHEN extract(day FROM d)=22 THEN 'absent_unexcused' ELSE 'day_off' END)) FROM generate_series('2026-02-01'::date,'2026-02-28'::date,'1 day') d)))$$,'Complete calendar reviewed without guessing');
SELECT lives_ok($$SELECT public.payroll_preparation_mutate('orders_review',jsonb_build_object('year',2026,'month',2,'driverId','a9500000-0000-4000-8000-000000000005','expectedVersion',(SELECT version FROM public.payroll_preparation_reviews WHERE driver_id='a9500000-0000-4000-8000-000000000005'),'delivered',0,'revenue',0,'note','Explicit zero orders confirmed'))$$,'Explicit zero-order review supported');
RESET ROLE;
INSERT INTO public.daily_order_entries(tenant_id,driver_id,platform_id,entry_date,orders_delivered,gross_revenue) VALUES('a9500000-0000-4000-8000-000000000001','a9500000-0000-4000-8000-000000000005','a9500000-0000-4000-8000-000000000007','2026-02-02',3,10.01);
SELECT is((SELECT orders_reviewed FROM public.payroll_preparation_reviews WHERE driver_id='a9500000-0000-4000-8000-000000000005'),false,'Source write invalidates order review');
SET LOCAL ROLE authenticated;
SELECT throws_ok($$SELECT public.payroll_preparation_mutate('orders_review',jsonb_build_object('year',2026,'month',2,'driverId','a9500000-0000-4000-8000-000000000005','expectedVersion',(SELECT version FROM public.payroll_preparation_reviews WHERE driver_id='a9500000-0000-4000-8000-000000000005'),'delivered',0,'revenue',0,'note','Stale aggregate reviewed'))$$,'P0001','PAY_ORDER_TOTALS_CHANGED','Stale aggregate cannot be approved');
SELECT lives_ok($$SELECT public.payroll_preparation_mutate('orders_review',jsonb_build_object('year',2026,'month',2,'driverId','a9500000-0000-4000-8000-000000000005','expectedVersion',(SELECT version FROM public.payroll_preparation_reviews WHERE driver_id='a9500000-0000-4000-8000-000000000005'),'delivered',3,'revenue',10.01,'note','Recorded source totals reviewed'))$$,'Actual exact order totals approved');
SELECT lives_ok($$UPDATE payroll_fixture SET advance_id=(public.payroll_preparation_mutate('advance_save','{"driverId":"a9500000-0000-4000-8000-000000000005","requestId":"a9500000-0000-4000-8000-000000000009","amount":12.34,"advanceDate":"2026-02-01","repaymentMonth":"2026-02","reason":"Driver advance request"}')->>'id')::uuid$$,'Pending advance created separately from expenses');
SELECT lives_ok($$SELECT public.payroll_preparation_mutate('advance_transition',jsonb_build_object('id',advance_id,'expectedVersion',1,'to','approved','note','Manager approved advance')) FROM payroll_fixture$$,'Advance approved');
SELECT throws_ok($$SELECT public.payroll_preparation_mutate('advance_transition',jsonb_build_object('id',advance_id,'expectedVersion',1,'to','approved','note','Replay of advance approval')) FROM payroll_fixture$$,'P0001','PAY_STALE_VERSION','Advance approval replay cannot double-apply');
SELECT throws_ok($$SELECT public.payroll_preparation_mutate('advance_save',jsonb_build_object('id',advance_id,'driverId','a9500000-0000-4000-8000-000000000005','expectedVersion',2,'amount',1,'advanceDate','2026-02-01','repaymentMonth','2026-02','reason','Try changing approved amount')) FROM payroll_fixture$$,'P0001','PAY_ADVANCE_HISTORY_IMMUTABLE','Approved advance financial history protected');
SELECT lives_ok($$SELECT public.payroll_preparation_mutate('lock',jsonb_build_object('year',2026,'month',2,'expectedVersion',(SELECT preparation_version FROM public.attendance_periods WHERE tenant_id='a9500000-0000-4000-8000-000000000001' AND period_year=2026 AND period_month=2),'note','Owner approved full source review'))$$,'Prepared period locks atomically');
RESET ROLE;
SELECT is((SELECT working_days_actual FROM public.driver_attendance_summary WHERE driver_id='a9500000-0000-4000-8000-000000000005'),20.50::numeric,'Working days sum exact entered statuses');
SELECT is((SELECT days_absent_unexcused::integer FROM public.driver_attendance_summary WHERE driver_id='a9500000-0000-4000-8000-000000000005'),1,'Absences derive only from entered statuses');
SELECT is((SELECT total_revenue FROM public.monthly_driver_orders WHERE driver_id='a9500000-0000-4000-8000-000000000005'),10.01::numeric,'Monthly order amount stays exact');
SELECT throws_ok($$UPDATE public.driver_attendance SET attendance_date='2026-03-01' WHERE driver_id='a9500000-0000-4000-8000-000000000005' AND attendance_date='2026-02-01'$$,'P0001','PAY_PREPARATION_LOCKED','Old source period cannot escape lock by changing date');
SELECT throws_ok($$INSERT INTO public.daily_order_entries(tenant_id,driver_id,platform_id,entry_date) VALUES('a9500000-0000-4000-8000-000000000001','a9500000-0000-4000-8000-000000000005','a9500000-0000-4000-8000-000000000007','2026-02-03')$$,'P0001','PAY_PREPARATION_LOCKED','New daily orders cannot enter locked period');
SELECT throws_ok($$UPDATE public.monthly_driver_orders SET total_revenue=1 WHERE driver_id='a9500000-0000-4000-8000-000000000005'$$,'P0001','PAY_PREPARATION_LOCKED','Locked derived amounts immutable even for owner');
SELECT throws_ok($$UPDATE public.attendance_periods SET status='open' WHERE tenant_id='a9500000-0000-4000-8000-000000000001' AND period_year=2026 AND period_month=2$$,'P0001','PAY_PREPARATION_LOCKED','Period cannot be silently reopened');
SET LOCAL ROLE authenticated;
SELECT throws_ok($$SELECT public.payroll_preparation_mutate('rule_archive',jsonb_build_object('id',rule_id,'expectedVersion',2,'note','Attempt archive of historic pay rule')) FROM payroll_fixture$$,'P0001','PAY_RULE_HISTORY_IMMUTABLE','Locked rule remains historical');
SELECT throws_ok($$SELECT public.payroll_preparation_mutate('advance_transition',jsonb_build_object('id',advance_id,'expectedVersion',2,'to','repaid','note','No paid payroll exists')) FROM payroll_fixture$$,'P0001','PAY_ADVANCE_PAID_PAYROLL_REQUIRED','Advance cannot be marked repaid without paid payroll');
RESET ROLE;
SELECT throws_ok($$INSERT INTO public.driver_payroll_periods(tenant_id,driver_id,period_year,period_month,advance_deduction) VALUES('a9500000-0000-4000-8000-000000000001','a9500000-0000-4000-8000-000000000005',2026,2,0)$$,'P0001','PAY_ADVANCE_SNAPSHOT_CHANGED','Calculation rejects a changed approved-advance snapshot');
SELECT set_config('request.jwt.claims','{}',true);
INSERT INTO public.driver_payroll_periods(id,tenant_id,driver_id,period_year,period_month,status,advance_deduction) VALUES('a9500000-0000-4000-8000-000000000008','a9500000-0000-4000-8000-000000000001','a9500000-0000-4000-8000-000000000005',2026,2,'paid',12.34);
SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claims','{"sub":"a9500000-0000-4000-8000-000000000003","role":"authenticated","aal":"aal2"}',true);
SELECT lives_ok($$SELECT public.payroll_preparation_mutate('advance_transition',jsonb_build_object('id',advance_id,'expectedVersion',2,'to','repaid','payrollPeriodId','a9500000-0000-4000-8000-000000000008','note','Repaid through matching paid payroll')) FROM payroll_fixture$$,'Paid payroll advance repayment recorded');
SELECT is((SELECT status FROM public.payroll_advances WHERE id=(SELECT advance_id FROM payroll_fixture)),'repaid','Advance is repaid');
SELECT is((SELECT payroll_period_id FROM public.payroll_advances WHERE id=(SELECT advance_id FROM payroll_fixture)),'a9500000-0000-4000-8000-000000000008'::uuid,'Repayment linked to paid payroll');
SELECT throws_ok($$SELECT public.payroll_preparation_mutate('advance_transition',jsonb_build_object('id',advance_id,'expectedVersion',3,'to','cancelled','note','Try deleting repaid history')) FROM payroll_fixture$$,'P0001','PAY_ADVANCE_TRANSITION_INVALID','Repaid history cannot be cancelled');
SELECT is((public.payroll_preparation_read(2026,2)->'drivers'->0->>'id'),'a9500000-0000-4000-8000-000000000005','Reader is tenant scoped');
SELECT is((public.payroll_periods_page(2026,0,'')->>'total')::integer,1,'Paging returns complete tenant count');
SELECT is((public.payroll_periods_page(2026,0,'nonexistent')->>'total')::integer,0,'Search count matches filter');
SELECT * FROM finish();
ROLLBACK;
